import { MakeLogicType, actions, afterMount, connect, kea, key, path, props, reducers, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import api from 'lib/api'
import { teamLogic } from 'scenes/teamLogic'

import type { SurveyQuestion } from '~/types'

import { surveysRetrieve } from '../generated/api'
import type { SurveyApi } from '../generated/api.schemas'

export interface SurveyObjectEmbedLogicProps {
    id: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface surveyObjectEmbedLogicValues {
    currentProjectId: number | string // teamLogic
    questions: SurveyQuestion[]
    responseCount: number | null
    responseCountLoading: boolean
    survey: SurveyApi | null
    surveyLoading: boolean
    surveyMissing: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface surveyObjectEmbedLogicActions {
    loadResponseCount: () => any
    loadResponseCountFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadResponseCountSuccess: (
        responseCount: number | null,
        payload?: any
    ) => {
        responseCount: number | null
        payload?: any
    }
    loadSurvey: () => any
    loadSurveyFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadSurveySuccess: (
        survey: SurveyApi | null,
        payload?: any
    ) => {
        survey: SurveyApi | null
        payload?: any
    }
    setSurveyMissing: () => {
        value: true
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface surveyObjectEmbedLogicMeta {
    key: string
    __keaTypeGenInternalSelectorTypes: {
        questions: (survey: SurveyApi | null) => SurveyQuestion[]
    }
}

export type surveyObjectEmbedLogicType = MakeLogicType<
    surveyObjectEmbedLogicValues,
    surveyObjectEmbedLogicActions,
    SurveyObjectEmbedLogicProps,
    surveyObjectEmbedLogicMeta
>

/**
 * Loads one survey for a read-only embed. It does not use `surveyLogic`, because that logic syncs its tabs and
 * filters to the page URL and so changes the URL of the page that shows the embed.
 */
export const surveyObjectEmbedLogic = kea<surveyObjectEmbedLogicType>([
    props({} as SurveyObjectEmbedLogicProps),
    key((props) => props.id),
    path((key) => ['products', 'surveys', 'posthogAi', 'surveyObjectEmbedLogic', key]),
    connect(() => ({ values: [teamLogic, ['currentProjectId']] })),
    actions({ setSurveyMissing: true }),
    loaders(({ props, values, actions }) => ({
        survey: [
            null as SurveyApi | null,
            {
                loadSurvey: async (): Promise<SurveyApi | null> => {
                    try {
                        return await surveysRetrieve(String(values.currentProjectId), props.id)
                    } catch (error: any) {
                        if (error.status === 404 || error.status === 400) {
                            actions.setSurveyMissing()
                            return null
                        }
                        throw error
                    }
                },
            },
        ],
        responseCount: [
            null as number | null,
            {
                // The generated client for this endpoint has no response type, so this uses the typed legacy call.
                loadResponseCount: async (): Promise<number | null> => {
                    const counts = await api.surveys.getResponsesCount(props.id)
                    return counts[props.id] ?? 0
                },
            },
        ],
    })),
    reducers({
        surveyMissing: [false, { setSurveyMissing: () => true }],
    }),
    selectors({
        questions: [
            (s) => [s.survey],
            // The serializer validates each question against the survey question types.
            (survey: SurveyApi | null): SurveyQuestion[] =>
                Array.isArray(survey?.questions) ? (survey.questions as SurveyQuestion[]) : [],
        ],
    }),
    afterMount(({ actions }) => {
        actions.loadSurvey()
        actions.loadResponseCount()
    }),
])
